00114     private function exec($args)
00115     {
00116         global $bearsamppCore;
00117 
00118         $command = '"' . Path::getNssmExe() . '" ' . $args;
00119         $this->writeLogInfo( 'Cmd: ' . $command );
00120 
00121         $result = Batch::exec( 'nssm', $command, 10 );
00122         if ( is_array( $result ) ) {
00123             $rebuildResult = array();
00124             foreach ( $result as $row ) {
00125                 $row = trim( $row );
00126                 if ( !empty( $row ) ) {
00127                     $rebuildResult[] = preg_replace( '/[\x00-\x1F\x80-\xFF]/', '', $row );
00128                 }
00129             }
00130             $result = $rebuildResult;
00131             if ( count( $result ) > 1 ) {
00132                 $this->latestError = implode( ' ; ', $result );
00133             }
00134 
00135             return $result;
00136         }
00137 
00138         return false;
00139     }
00140 
00148     public function status($timeout = true)
00149     {
00150         $this->latestStatus = self::STATUS_NA;
00151         $maxtime            = time() + self::PENDING_TIMEOUT;
00152 
00153         while ( $this->latestStatus == self::STATUS_NA || $this->isPending( $this->latestStatus ) ) {
00154             $exec = $this->exec( 'status ' . $this->getName() );
00155             if ( $exec !== false ) {
00156                 if ( count( $exec ) > 1 ) {
00157                     $this->latestStatus = self::STATUS_NOT_EXIST;
00158                 }
00159                 else {
00160                     $this->latestStatus = $exec[0];
00161                 }
00162             }
00163             if ( $timeout && $maxtime < time() ) {
00164                 break;
00165             }
00166 
00167             // Only sleep if we're going to loop again
00168             if ($this->latestStatus == self::STATUS_NA || $this->isPending($this->latestStatus)) {
00169                 usleep(self::SLEEP_TIME);
00170             }
00171         }
00172 
00173         if ( $this->latestStatus == self::STATUS_NOT_EXIST ) {
00174             $this->latestError  = 'Error 3: The specified service does not exist as an installed service.';
00175             $this->latestStatus = self::STATUS_NA;
00176         }
00177 
00178         return $this->latestStatus;
00179     }
