00186     public function create()
00187     {
00188         $this->writeLog( 'Create service' );
00189         $this->writeLog( '-> service: ' . $this->getName() );
00190         $this->writeLog( '-> display: ' . $this->getDisplayName() );
00191         $this->writeLog( '-> description: ' . $this->getDisplayName() );
00192         $this->writeLog( '-> path: ' . $this->getBinPath() );
00193         $this->writeLog( '-> params: ' . $this->getParams() );
00194         $this->writeLog( '-> stdout: ' . $this->getStdout() );
00195         $this->writeLog( '-> stderr: ' . $this->getStderr() );
00196         $this->writeLog( '-> environment extra: ' . $this->getEnvironmentExtra() );
00197         $this->writeLog( '-> start_type: ' . ($this->getStart() != null ? $this->getStart() : self::SERVICE_DEMAND_START) );
00198 
00199         // Install bin
00200         $exec = $this->exec( 'install ' . $this->getName() . ' "' . $this->getBinPath() . '"' );
00201         if ( $exec === false ) {
00202             return false;
00203         }
00204 
00205         // Params
00206         $exec = $this->exec( 'set ' . $this->getName() . ' AppParameters "' . $this->getParams() . '"' );
00207         if ( $exec === false ) {
00208             return false;
00209         }
00210 
00211         // DisplayName
00212         $exec = $this->exec( 'set ' . $this->getName() . ' DisplayName "' . $this->getDisplayName() . '"' );
00213         if ( $exec === false ) {
00214             return false;
00215         }
00216 
00217         // Description
00218         $exec = $this->exec( 'set ' . $this->getName() . ' Description "' . $this->getDisplayName() . '"' );
00219         if ( $exec === false ) {
00220             return false;
00221         }
00222 
00223         // No AppNoConsole to fix nssm problems with Windows 10 Creators update.
00224         $exec = $this->exec( 'set ' . $this->getName() . ' AppNoConsole "1"' );
00225         if ( $exec === false ) {
00226             return false;
00227         }
00228 
00229         // Start
00230         $exec = $this->exec( 'set ' . $this->getName() . ' Start "' . ($this->getStart() != null ? $this->getStart() : self::SERVICE_DEMAND_START) . '"' );
00231         if ( $exec === false ) {
00232             return false;
00233         }
00234 
00235         // Stdout
00236         $exec = $this->exec( 'set ' . $this->getName() . ' AppStdout "' . $this->getStdout() . '"' );
00237         if ( $exec === false ) {
00238             return false;
00239         }
00240 
00241         // Stderr
00242         $exec = $this->exec( 'set ' . $this->getName() . ' AppStderr "' . $this->getStderr() . '"' );
00243         if ( $exec === false ) {
00244             return false;
00245         }
00246 
00247         // Environment Extra
00248         $exec = $this->exec( 'set ' . $this->getName() . ' AppEnvironmentExtra ' . $this->getEnvironmentExtra() );
00249         if ( $exec === false ) {
00250             return false;
00251         }
00252 
00253         if ( !$this->isInstalled() ) {
00254             $this->latestError = null;
00255 
00256             return false;
00257         }
00258 
00259         return true;
00260     }
