00351     public function infos()
00352     {
00353         global $bearsamppRegistry;
00354 
00355         $infos = Win32Native::getServiceInfo( $this->getName() );
00356         if ( $infos === false ) {
00357             return false;
00358         }
00359 
00360         $infosNssm = array();
00361         $infosKeys = array(
00362             self::INFO_APPLICATION,
00363             self::INFO_APP_PARAMETERS,
00364         );
00365 
00366         foreach ( $infosKeys as $infoKey ) {
00367             $value  = null;
00368             $exists = $bearsamppRegistry->exists(
00369                 Registry::HKEY_LOCAL_MACHINE,
00370                 'SYSTEM\CurrentControlSet\Services\\' . $this->getName() . '\Parameters',
00371                 $infoKey
00372             );
00373             if ( $exists ) {
00374                 $value = $bearsamppRegistry->getValue(
00375                     Registry::HKEY_LOCAL_MACHINE,
00376                     'SYSTEM\CurrentControlSet\Services\\' . $this->getName() . '\Parameters',
00377                     $infoKey
00378                 );
00379             }
00380             $infosNssm[$infoKey] = $value;
00381         }
00382 
00383         if ( !isset( $infosNssm[self::INFO_APPLICATION] ) ) {
00384             return $infos;
00385         }
00386 
00387         $infos[Win32Service::VBS_PATH_NAME] = $infosNssm[Nssm::INFO_APPLICATION] . ' ' . $infosNssm[Nssm::INFO_APP_PARAMETERS];
00388 
00389         return $infos;
00390     }
