00464     private function getServiceStatusDesc($status)
00465     {
00466         switch ( $status ) {
00467             case self::STATUS_CONTINUE_PENDING:
00468                 return 'The service continue is pending.';
00469 
00470             case self::STATUS_PAUSE_PENDING:
00471                 return 'The service pause is pending.';
00472 
00473             case self::STATUS_PAUSED:
00474                 return 'The service is paused.';
00475 
00476             case self::STATUS_RUNNING:
00477                 return 'The service is running.';
00478 
00479             case self::STATUS_START_PENDING:
00480                 return 'The service is starting.';
00481 
00482             case self::STATUS_STOP_PENDING:
00483                 return 'The service is stopping.';
00484 
00485             case self::STATUS_STOPPED:
00486                 return 'The service is not running.';
00487 
00488             case self::STATUS_NA:
00489                 return 'Cannot retrieve service status.';
00490 
00491             default:
00492                 return null;
00493         }
00494     }
